#nullable enable // autogenerated

using MVZ2Logic.Models;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    public class HookshotChainsModel : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            base.UpdateFrame(deltaTime);
            var source = sourceTransform.position;
            var dest = Lawn2TransPosition(Model.GetProperty<Vector3>("Dest"));
            var distance = dest - source;
            sourceTransform.rotation = Quaternion.FromToRotation(Vector3.right, distance);

            var height = chainRenderer.sprite.rect.height;
            chainRenderer.size = new Vector2(distance.magnitude, height * 0.01f);
        }
        [SerializeField]
        private Transform sourceTransform = null!;
        [SerializeField]
        private SpriteRenderer chainRenderer = null!;
    }
}
